import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function AdminDashboard() {

  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  useEffect(() => {
    fetchQueues();

    socket.on("queueUpdated", fetchQueues);

    return () => socket.off();
  }, []);

  // CONFIRM OP
  const confirmOP = async (id) => {
    await fetch(`http://localhost:5000/api/queue/confirm/${id}`, {
      method: "PUT"
    });
  };

  // COMPLETE OP
  const completeOP = async (id) => {
    await fetch(`http://localhost:5000/api/queue/complete/${id}`, {
      method: "DELETE"
    });
  };

  return (
    <div style={{ padding: 20 }}>

      <h2>👨‍⚕️ Admin Dashboard</h2>

      {queues.map((q) => (
        <div key={q._id} style={{ border: "1px solid black", margin: 10, padding: 10 }}>

          <p><b>Patient:</b> {q.patientName}</p>
          <p><b>Doctor:</b> {q.doctor}</p>
          <p><b>Status:</b> {q.status}</p>

          {/* CONFIRM BUTTON */}
          {q.status === "Waiting" && (
            <button onClick={() => confirmOP(q._id)}>
              Confirm OP
            </button>
          )}

          {/* COMPLETE BUTTON */}
          <button onClick={() => completeOP(q._id)}>
            Complete OP
          </button>

        </div>
      ))}

    </div>
  );
}

export default AdminDashboard;
